.libPaths(c(file.path(Sys.getenv("W"), "lib"), .libPaths())); library(zujson)
cl <- function(expr) tryCatch({expr; "ok"}, condition=function(e) class(e)[1])
nj <- function(n, inner="") paste0(strrep("[", n), inner, strrep("]", n))
nl <- function(n, leaf=list()) { x <- leaf; for (i in seq_len(n-1)) x <- list(x); x }
no <- function(n) paste0(strrep('{"a":', n-1), "{}", strrep("}", n-1))
for (n in c(999,1000,1001)) cat(n, "parse arr:", cl(json_parse(nj(n))), "| none:", cl(json_parse(nj(n), simplify="none")), "| coerce:", cl(json_parse(nj(n), simplify="coerce")), "| df:", cl(json_parse(nj(n), data_frame=TRUE)), "| raw:", cl(json_parse_raw(charToRaw(nj(n)))), "| obj:", cl(json_parse(no(n))), "| scalar leaf:", cl(json_parse(nj(n, "1"))), "| validate:", json_validate(nj(n)), "| ndjson:", cl(json_parse_ndjson(nj(n))), "| write list:", cl(json_write(nl(n))), "| write leaf vec:", cl(json_write(nl(n, 1:2))), "| write leaf scalar:", cl(json_write(nl(n+1, 1))), "| ndjson w:", cl(json_write_ndjson(list(nl(n)))), "\n")
# write-then-parse at the boundary: anything written must parse
for (n in c(998,999,1000,1001)) { x <- nl(n, 1:2); w <- tryCatch(json_write(x), error=function(e) NULL); cat(n, "leaf vec written:", !is.null(w), "parses:", if (!is.null(w)) cl(json_parse(w)) else NA, "\n") }
# data frame depth: df nested in lists
df <- data.frame(a=1:2); df$l <- list(1:2, 3:4)
for (n in c(996,997,998,999,1000)) { x <- nl(n, df); w <- tryCatch(json_write(x), error=function(e) NULL); cat(n, "wrap+df(listcol) written:", !is.null(w), "parses:", if (!is.null(w)) paste(cl(json_parse(w)), cl(json_parse(w, data_frame=TRUE))) else NA, "\n") }
f <- tempfile(); writeBin(charToRaw(nj(1001)), f); cat("file 1001:", cl(json_parse_file(f)), "\n"); writeBin(charToRaw(nj(1000)), f); cat("file 1000:", cl(json_parse_file(f)), "\n")
# parse df depth: array of objects whose cells are nested
for (n in c(997,998,999,1000)) { j <- paste0(strrep("[", n), '{"a":[1]}', strrep("]", n)); cat(n, "+obj+arr parse:", cl(json_parse(j)), "df:", cl(json_parse(j, data_frame=TRUE)), "\n") }
cat("info depth", zujson_info()$max_depth, "\n")
cat("--- misc write\n")
t <- function(label, expr) { r <- tryCatch(expr, condition = function(e) paste0("<", paste(class(e), collapse="/"), "> ", conditionMessage(e))); cat(sprintf("%-30s %s\n", label, paste(format(r), collapse=" | "))) }
t("classed list", json_write(structure(list(a=1,b="x"), class="foo")))
t("classed chr json", json_write(structure('{"a":1}', class="json")))
t("attr vector", json_write(structure(1:3, foo="bar")))
t("names w/ dims", json_write(array(1:3, dim=3, dimnames=list(c("a","b","c")))))
t("matrix w/ names attr", json_write(structure(1:4, dim=c(2,2), names=c("a","b","c","d"))))
t("list matrix", json_write(matrix(list(1,"a",NULL,TRUE),2)))
t("nested NULL in named", json_write(list(a=NULL, b=list(NULL))))
t("list of len0", json_write(list(a=integer(), b=character(), c=NULL, d=list(), e=logical())))
t("names space", json_write(c(` `=1)))
t("names quote/nl", json_write(setNames(list(1), "a\"b\nc")))
t("name 'NA' string", json_write(c("NA"=1)))
t("NA_character_ name on list", json_write(setNames(list(1,2), c(NA,"b"))))
t("long string", nchar(json_write(strrep("x", 1e6))))
t("many elements", nchar(json_write(seq_len(1e6))))
t("altrep seq", json_write(1:5)); t("altrep rev", json_write(5:1)); t("altrep chr", json_write(as.character(1:3)))
t("deferred string in list", json_write(list(a=as.character(1e5), b=as.character(123456.7))))
t("int NA in named", json_write(c(a=NA_integer_, b=1L)))
t("-0.0 rt", 1/json_parse(json_write(-0)))
t("dbl ints", json_write(c(1, 2.5, 3))); t("3.0e0", json_write(3)); t("-1e15", json_write(-123456789012345678))
t("1e15+0.5", json_write(1e15+0.5)); t("2^53-1", json_write(2^53-1)); t("-2^53", json_write(-2^53)); t("9.2e18", json_write(9.2e18)); t("2^63-1024", json_write(2^63-1024)); t("-2^63-2048", json_write(-2^63-2048))
t("rt 2^63", json_parse(json_write(2^63)) == 2^63); t("rt 2^63-1024", json_parse(json_write(2^63-1024)) == 2^63-1024); t("rt -2^63", json_parse(json_write(-2^63)) == -2^63)
t("rt whole doubles", {x <- c(2^53+2, 2^62, -2^62, 1e18, 123456789012345680, 2^63-1024, 4611686018427387904); identical(json_parse(json_write(x)), x)})
set.seed(1); x <- c(runif(2000, -1e6, 1e6), 10^runif(2000, -300, 300), .Machine$double.eps, 2^(-1074:-1060), 2^(1000:1023)); t("rt random doubles", identical(json_parse(json_write(x)), x))
xi <- c(sample.int(.Machine$integer.max, 1000), -sample.int(.Machine$integer.max, 1000), 0L, NA, .Machine$integer.max, -.Machine$integer.max); t("rt ints", identical(json_parse(json_write(xi)), xi))
xw <- round(runif(2000, -2^62, 2^62)); t("rt whole big", identical(as.double(json_parse(json_write(xw))), xw))
s <- c("", " ", "a\"b", "\\", "  ", "\x7f", "\t\n\r\b\f", "\U0001F600", "é", "﻿", "\u0001\u001f", "</script>", "NA", "null", "true", "1"); Encoding(s) <- "UTF-8"; t("rt strings", identical(json_parse(json_write(s)), s))
t("rt strings ndjson", identical(json_parse_ndjson(json_write_ndjson(as.list(s))), as.list(s)))
t("rt nested", {x <- list(a=1L, b=list(c="x", d=c(1.5,2.5), e=list(TRUE, "z")), f=NULL, g=c(TRUE,NA)); identical(json_parse(json_write(x)), x)})
t("rt keys", {k <- c("", "a b", "é", "a\"b", "\n", "NA", "1"); x <- setNames(as.list(1:7), k)[-1]; identical(json_parse(json_write(x)), x)})
t("rt pretty", {x <- list(a=1L, b=list(c="x\n", d=c(1.5,2.5)), e=list()); identical(json_parse(json_write(x, pretty=TRUE)), json_parse(json_write(x)))})
t("ctrl 0x7f/0x1f", json_write("\x1f\x7f"))
t("write list w/ NULL names elt", json_write(list(a=1, 2, b=3)))
t("env in list", json_write(list(a=1, e=new.env())))
t("fn in df list col", {d <- data.frame(a=1); d$f <- list(sum); json_write(d)})
t("write quote(x) in list", json_write(list(quote(x))))
t("lang obj formula in list", json_write(list(y~x)))
t("date in named vec noAU", json_write(list(d=Sys.Date()[0])))
t("factor(0)", json_write(factor(character())))
t("Date named len1", json_write(c(a=as.Date("2024-01-01"))))
t("POSIXct list", json_write(list(as.POSIXct(c(0,NA,1.5), origin="1970-01-01", tz="UTC"))))
t("POSIXct 1e-9 neg", json_write(as.POSIXct(-1e-9, origin="1970-01-01", tz="UTC")))
t("POSIXct .999999999", json_write(.POSIXct(1699999999.9999999, tz="UTC")))
t("POSIXct Inf/NaN", json_write(.POSIXct(c(Inf,-Inf,NaN), tz="UTC")))
t("Date NaN/-Inf", json_write(.Date(c(NaN,-Inf))))
t("POSIXct leap", json_write(as.POSIXct("2016-12-31 23:59:60", tz="UTC")))
t("POSIXct vs format", {x <- .POSIXct(c(-62167219200, -1e10, -86401, -1, 0, 951782400, 4102444800, 253402300799, 1e9+0.7), tz="UTC"); identical(json_parse(json_write(x)), format(x, "%Y-%m-%dT%H:%M:%SZ", tz="UTC"))})
t("Date vs format", {x <- .Date(c(-719528, -141427, -1, 0, 59, 60, 11016, 19782, 2932896, 47541, -25567)); identical(json_parse(json_write(x)), format(x, "%Y-%m-%d"))})
set.seed(2); t("Date random vs format", {x <- .Date(sample(-719528:2932896, 5000)); identical(json_parse(json_write(x)), format(x, "%Y-%m-%d"))})
t("POSIXct random vs format", {x <- .POSIXct(round(runif(5000, -62167219200, 253402300799)), tz="UTC"); identical(json_parse(json_write(x)), format(x, "%Y-%m-%dT%H:%M:%SZ"))})
